{\it Assume that $\phi$ is Anosov and topological mixing on fibers. Then, for any $\epsilon>0$, there exists $N\in\mathbb N$ such that for any $g\in L^{\infty}(\Omega)$ and $n\ge N$, there exists a random periodic point $\tilde g$ with period $n$ such that
 \begin{equation*}
  d_{L^{\infty}}(g,\tilde g)\le \epsilon.
 \end{equation*}
 }

{\it Assume that $\phi$ is  Anosov and topological mixing on fibers. Then the following statements hold
\begin{itemize}
\item[(a)] Strong Random Horseshoe: For any $\gamma>0$, there exist $N,k\in \mathbb N$ such that the following hold
   \begin{enumerate}
     \item[i)] $\frac1N\ln k\ge \underline{h}(M\times\Omega|\Omega)-\gamma$, where $\underline{h}(M\times\Omega|\Omega)>0$ and \[\underline{h}(M\times\Omega|\Omega):=\inf_{\omega\in\Omega} h_{top}(\phi|_{M_\omega});\]
     \item[ii)] $\phi^N$ has a $k$-symbol strong full random horseshoe.
   \end{enumerate}
\item[(b)] Random Horseshoe: For any $\gamma>0$,  there exist $N,k\in \mathbb N$ such that the following hold
   \begin{enumerate}
     \item[i)] $\frac1N\ln k\ge \overline{h}(M\times\Omega|\Omega)-\gamma$, where $\overline{h}(M\times\Omega|\Omega)>0$ and
      \[\overline{h}(M\times\Omega|\Omega):=\sup_{\omega\in\Omega} h_{top}(\phi|_{M_\omega});\]
     \item[ii)] $\phi^N$ has a $k$-symbol full random horseshoe.
   \end{enumerate}
 \end{itemize}
 }

\label{T:TheoryAnosovMix}
 Let $\phi$ satisfy condition  H1) and H2). Then, for any $\epsilon>0$, there exists $N\in\mathbb N$ such that for any $g\in L^{\infty}(\Omega)$ and $n\ge N$, there exists a random periodic point $\tilde g$ with period $n$ such that
 \begin{equation*}\label{E:LInfiClose2}              
  d_{L^{\infty}}(g,\tilde g)\le \epsilon.
 \end{equation*}

\label{T:TheoryAnosovMix2}
 Let $\phi$ satisfy condition H1)and H2). Then the following assertions hold:
 \begin{itemize}
  \item[{\bf A.}]  For any $\gamma>0$, there exist $N,k\in \mathbb N$ such that the following hold
   \begin{enumerate}
     \item[i)] $\frac1N\ln k\ge \underline{h}(M\times\Omega|\Omega)-\gamma$, where $\underline{h}(M\times\Omega|\Omega)>0$;
     \item[ii)] $\phi^N$ has a $k$-symbol strong full random horseshoe.
   \end{enumerate}
   \item[{\bf B.}] For any $\gamma>0$,  there exist $N,k\in \mathbb N$ such that the following hold
   \begin{enumerate}
     \item[i)] $\frac1N\ln k\ge \overline{h}(M\times\Omega|\Omega)-\gamma$;
     \item[ii)] $\phi^N$ has a $k$-symbol full random horseshoe.
   \end{enumerate}
 \end{itemize}

\label{L:InvMani}          
For any $\lambda\in (0,\lambda_0)$, there exists $\epsilon_0>0$ such that for any $\epsilon\in(0,\epsilon_0]$, the following hold:
\begin{itemize}
\item[i)] $W^s_\epsilon(x,\omega), W^u_\epsilon(x,\omega)$ are $C^2$-embedded discs for all $(x,\omega)\in M\times \Omega$ which satisfy \[T_xW_\epsilon^\tau(x,\omega)=E^\tau_{(x,\omega)}, \text{for}
    ;\tau=u,s.\]
Moreover,  there exist a constant $L>1$ and $C^2$ maps
$$g^u_{(x,\omega)}:B^u_{\mathcal P\epsilon}(x,\omega)\to E^s_{(x,\omega)} \text{ and }g^s_{(x,\omega)}:B^s_{\mathcal P\epsilon}(x,\omega)\to E^u_{(x,\omega)} $$
such that $$W^\tau_\epsilon(x,\omega)\subset Exp_{(x,\omega)}\left(graph(g^\tau_{(x,\omega)})\right),$$ and $\|Dg^\tau_{(x,\omega)}\|<\frac1{10\mathcal P}$,  $Lip Dg^\tau_{(x,\omega)}<L$ for $\tau=u,s$, where $\mathcal P$ is as in (\ref{E:PrjBound}) and $B^\tau_{\mathcal P \epsilon}(x,\omega)$ is the $\mathcal P\epsilon$-ball of $E^\tau_{(x,\omega)}$ centered at  origin;
\item[ii)] $d_M(\pi_M\phi^n(x,\omega),\pi_M\phi^n(y,\omega))\le e^{-n\lambda}d_M(x,y)$ for $(y,\omega)\in W^s_\epsilon(x,\omega)$, $n\ge 0$, and\\
$d_M(\pi_M\phi^{-n}(x,\omega),\pi_M\phi^{-n}(y,\omega))\le e^{-n\lambda}d_M(x,y)$ for $(y,\omega)\in W^u_\epsilon(x,\omega)$, $n\ge 0$;
\item[iii)] $W^s_\epsilon(x,\omega), W^u_\epsilon(x,\omega)$ vary continuously on $(x,\omega)$ (in $C^1$ topology).
\end{itemize}

\label{L:AlDefH}         
Suppose  that $\phi$ satisfy Condition H1). Then the following holds:
$$\underline h(M\times \Omega|\Omega)=\lim_{\epsilon\to0^+}\inf_{\omega\in\Omega}\limsup_{n\to\infty}\frac1n\log N(\omega,\epsilon,n),$$ where
\begin{align*}
&N(\omega,\epsilon,n):=\\&\max\  \left\{card(E)\big|\ E\subset M_{\omega}, E \text{ is an }\epsilon\text{ separated set with respect to }d^{\phi}_{M\times \Omega,n}\right\}.
\end{align*}

\label{L:ContiG}         
  For any $(x,\omega)\in M\times\Omega$, $g\in C(\Omega,M)$, and an open neighborhood $V\subset \Omega$ of $\omega$,  there exist an nonempty open set $A\subset\Omega\setminus\{\omega\}$ with $\Omega\setminus A\subset V$ and a function $g'\in C(\Omega,M)$ such that
 \begin{equation}\label{E:g'}     
 g'(\omega)=x\text{ and }g'|_A=g|_A.
 \end{equation}

\label{C:T^2Horseshoe}               
For any $\gamma>0$ there exist $N,k$ such that the following hold:

\begin{itemize}
\item[i)] $\frac1N\log k>\log \kappa-\gamma$;
\item[ii)] $\hat \phi^N$ has a strong full random horseshoe with $k$ symbols.
\end{itemize}
Here $\kappa$ is given by (\ref{E:AssumpExpan}).

\label{T:PHorseshoe}             
 Let $\phi$ satisfy H1) and H2) and $\mathbb P$ be a $\theta$-ergodic probability measure. Then for any $\gamma>0$,  there exist $N,k\in \mathbb N$ such that the following hold
   \begin{enumerate}
     \item[i)] $\frac1N\ln k\ge h_{top}(M\times\Omega|\mathbb P)-\gamma$;
     \item[ii)] $\phi^N$ has a $k$-symbol random horseshoe on marginal $\mathbb P$.
   \end{enumerate}

\label{T:SPHorseshoe}              
 Let $\phi$ be an S1) system and $\mathbb P$ be the unique $\theta$-ergodic probability measure. Then for any $\gamma>0$,  there exist $N,k\in \mathbb N$ such that the following hold
   \begin{enumerate}
     \item[i)] $\frac1N\ln k\ge h_{top}(M\times\Omega|\mathbb P)-\gamma$;
     \item[ii)] $\phi^N$ has a $k$-symbol strong random horseshoe on marginal $\mathbb P$.
   \end{enumerate}

